      function xForOperatorCount(index, total) {
        const laneLeft = PLAY_LEFT + LANE_EDGE_PADDING;
        const laneRight = PLAY_RIGHT - LANE_EDGE_PADDING;
        if (total <= 1) return Math.round((laneLeft + laneRight) / 2);
        return laneLeft + Math.round(index * (laneRight - laneLeft) / (total - 1));
      }

